function validate([peaks]) {
  if (!Array.isArray(peaks) || peaks.length < 1 || peaks.length > 100000) return 'peaks needs 1 to 10^5 mountains.';
  for (const peak of peaks) {
    if (!Array.isArray(peak) || peak.length !== 2) return 'Each peak is a pair [x, y].';
    if (peak.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each coordinate is a whole number from 1 to 10^5.';
  }
  return null;
}

