function visibleMountains(peaks) {
  const intervals = peaks.map(([x, y]) => [x - y, x + y]);
  intervals.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  let count = 0;
  let maxRight = -Infinity;
  for (let i = 0; i < intervals.length; i++) {
    const [left, right] = intervals[i];
    if (right <= maxRight) {
      continue;
    }
    maxRight = right;
    const next = intervals[i + 1];
    if (next && next[0] === left && next[1] === right) {
      continue;
    }
    count++;
  }
  return count;
}

