function visibleMountains(peaks) {
  // Mountain j's height above x is yj - |x - xj|; top i is hidden when it is not above that height.
  let visible = 0;
  for (let i = 0; i < peaks.length; i++) {
    let hidden = false;
    for (let j = 0; j < peaks.length && !hidden; j++) {
      if (j !== i && peaks[i][1] <= peaks[j][1] - Math.abs(peaks[i][0] - peaks[j][0])) hidden = true;
    }
    if (!hidden) visible++;
  }
  return visible;
}

