function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8);
    const span = pick(3, 10);
    return [Array.from({ length: n }, () => [pick(1, span), pick(1, span)])];
  }
  // Large: many small or mid-sized mountains spread along the axis, with some exact repeats.
  const n = pick(1500, 2000);
  const tall = [300, 3000, 30000][pick(0, 2)];
  const peaks = [];
  for (let i = 0; i < n; i++) {
    if (peaks.length && rand() < 0.1) peaks.push([...peaks[pick(0, peaks.length - 1)]]);
    else peaks.push([pick(1, 100000), pick(1, tall)]);
  }
  return [peaks];
}
